"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8539],{78539:e=>{e.exports=JSON.parse('{"slug":"zanyatost-ssha-sentyabr-realnye-zarplaty","locale":"zh","title":"美国新增就业仅及预期三分之一（3倍差距），工资跑输物价","description":"美国九月新增29千岗位，预期90千；工资增3%，通胀3.4%。解释实际工资及美联储利率前景。","blocks":[{"id":"b001","kind":"paragraph","text":"美国劳工部于2026年十月2日公布，九月新增29千岗位，预期约90千。七八月合计下修60千，失业率由4.1%升至4.2%。医疗增17千、建筑11千最多，金融少7千。"},{"id":"b002","kind":"paragraph","text":"工资是九月报告最弱部分。平均时薪环比仅0.1%，为2025年十二月以来最低；同比3%，2021年五月以来最慢。最新八月物价同比3.4%，美国人能用工资买到的比一年前少。"},{"id":"b003","kind":"paragraph","text":"这就是名义与实际工资差别。名义是工资单金额，实际是可购买多少，通常用工资增幅减物价增幅。九月工资与八月通胀相比，美国实际约跌0.4%（1.03 / 1.034）。俄罗斯2026年七月平均名义增9.5%至109.5千卢布，实际增3.3%。比较仅近似，两国月份及方法不同。俄罗斯也略放缓，六月为3.4%。"},{"id":"b004","kind":"paragraph","text":"弱就业使美联储不必急。十月27–28日加息概率一周由64%降约20%，先受通胀数据、后受就业影响。但3.4%仍远高2%目标，市场预期的是推迟而非放弃，高盛等大行仍预计十二月加。10年期美债收益率报告后先跌，日末升至5.28%。当前政策区间3.75–4%。"},{"id":"b005","kind":"paragraph","text":"俄罗斯读者通过美元受影响，方向矛盾：推迟加息降低美元吸引力，十月5日周一兑其他货币略弱；但美债仍超5%，支持需求。俄罗斯卢布、价格和利率更受石油与本国央行影响。下一美国就业报告十一月6日公布，已晚于十月会议。"},{"id":"b006","kind":"paragraph","text":"持美元者若因弱报告卖出，是押注美联储完全放弃加息，无人承诺；若押注美元涨买入，也有失业继续上升、十二月加息取消的风险。劳动力疲弱是否成趋势尚未知。"},{"id":"b007","kind":"heading","text":"美国2026年九月新增多少岗位？"},{"id":"b008","kind":"paragraph","text":"29千，预期约90千；七八月下修60千，失业率4.1%升4.2%。"},{"id":"b009","kind":"heading","text":"实际工资是什么？"},{"id":"b010","kind":"paragraph","text":"计入物价后的购买力。美国工资同比3%，通胀3.4%，实际约降0.4%；俄罗斯七月实际增3.3%。"},{"id":"b011","kind":"heading","text":"弱就业后美联储会加息吗？"},{"id":"b012","kind":"paragraph","text":"十月可能性较低，市场约20%，一周前64%。但市场和大行仍预计十二月加，当前区间3.75–4%。"}],"sources":[{"label":"美国九月就业低于预期：新增29,000，失业率上升","url":"https://finance.yahoo.com/economy/article/septembers-jobs-report-shows-the-us-added-just-29000-jobs-and-unemployment-ticked-up-195320409.html"},{"label":"通胀数月侵蚀工资增长，九月仍然如此","url":"https://finance.yahoo.com/economy/article/inflation-has-been-eating-up-wage-gains-for-months-september-was-no-better-180727718.html"},{"label":"全球经济：美国招聘和工资增长放缓","url":"https://www.bloomberg.com/news/articles/2026-10-03/world-economy-latest-us-employers-dial-back-hiring-wage-growth-slows"},{"label":"加息概率降温，Nasdaq上涨319点","url":"https://www.kiplinger.com/investing/stocks/nasdaq-adds-319-points-as-rate-hike-odds-ebb-stock-market-today"},{"label":"29K就业报告对十月加息与利率的意义","url":"https://www.fxstreet.com/analysis/the-october-fed-hike-just-died-heres-what-the-29k-jobs-report-really-means-for-rates-202610021806"},{"label":"弱就业降低十月加息概率，美债收益率先跌","url":"https://www.indexbox.io/blog/treasury-yields-fall-after-weak-september-jobs-report-cuts-odds-of-october-fed-rate-hike/"},{"label":"美股走强、美元波动，加息押注降温","url":"https://www.investing.com/news/economy-news/stocks-upbeat-dollar-wobbles-as-fed-hike-bets-recede-4930982"},{"label":"就业报告发布日程","url":"https://www.bls.gov/schedule/news_release/empsit.htm"},{"label":"俄罗斯七月实际工资增速降至3.3%","url":"https://ru.themoscowtimes.com/2026/09/30/rost-realnykh-zarplat-v-rf-v-iyule-26g-zamedlilsya-do-33-gg-a207452"}],"sourceBodySha256":"8dbaae3cc9570f53146a348a9d62855bcdad77232b7be2422c1b98c268553b25"}')}}]);